import fs from 'node:fs';import path from 'node:path';import {createHash} from 'node:crypto';
import {timingDistribution,validateTiming} from '../live-paper/read-timing.mjs';
const runtime=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),start='2026-10-05T20:35:00.000Z',end='2026-10-05T20:57:15.000Z';
const raw=fs.readFileSync(path.join(runtime,'read-timings.jsonl'),'utf8'),complete=raw.slice(0,raw.lastIndexOf('\n')+1);
const rows=complete.trimEnd().split('\n').map(line=>({line,event:validateTiming(JSON.parse(line))})).filter(({event:e})=>Date.parse(e.queuedAt)>=Date.parse(start)&&Date.parse(e.finishedAt)<Date.parse(end));
const events=rows.map(x=>x.event),groups={};for(const e of events){const g=groups[e.kind]??={requests:0,totalClientMs:0,serviceMs:0,admissionMs:0};g.requests++;g.totalClientMs+=e.totalMs||0;g.serviceMs+=e.serviceMs||0;g.admissionMs+=e.admissionWaitMs||0;}
