const result={schemaVersion:1,observedFrom:start,observedThrough:end,source:'existing serialized collector read-timings.jsonl; complete successful and unsuccessful receipts',windowSha256:createHash('sha256').update(rows.map(x=>x.line+'\n').join('')).digest('hex'),requests:events.length,groups,bookRecurrence,implementation:{rateBudgetChanged:false,extraClients:0,bookDepth:20,ordinaryBookCap:4,officialWrites:0,sprintLifetimeMaxMs:3600000,expectedRemovedRequestsPerOwnedSourceCycle:5},limits:['Baseline observation; postdeployment speed is not established','Five removed calls assumes two unrelated discovery books, two optional breadth batches and one auxiliary read; metadata/liabilities reduce savings','No observed strategy profitability is implied']};
fs.writeFileSync(new URL('./profit-sprint-read-baseline-20261005.json',import.meta.url),JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({requests:result.requests,bookRecurrence,groups}));
